package com.minimarket.producto.controller; import org.springframework.security.access.prepost.PreAuthorize;
import com.minimarket.common.ApiResponse; import com.minimarket.producto.dto.*; import com.minimarket.producto.service.MarcaService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @PreAuthorize("hasAuthority('CATALOGO_ADMINISTRAR')") @RequestMapping("/api/marcas") @RequiredArgsConstructor public class MarcaController{private final MarcaService s;@GetMapping public ApiResponse<Page<MarcaResponseDTO>> listar(Pageable p){return ApiResponse.ok(s.listar(p));}@GetMapping("/{id}")public ApiResponse<MarcaResponseDTO> obtener(@PathVariable Long id){return ApiResponse.ok(s.obtener(id));}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ApiResponse<MarcaResponseDTO> crear(@Valid @RequestBody MarcaRequestDTO r){return ApiResponse.ok(s.crear(r));}@PutMapping("/{id}")public ApiResponse<MarcaResponseDTO> actualizar(@PathVariable Long id,@Valid @RequestBody MarcaRequestDTO r){return ApiResponse.ok(s.actualizar(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> desactivar(@PathVariable Long id){s.desactivar(id);return ApiResponse.ok(null,"Marca desactivada");}}